$('#fan').onclick=()=>setMode('fan');$('#jet').onclick=()=>setMode('jet');$('#upgrade').onclick=()=>{const cost=120*(upgrade+1);if(upgrade>=3)return toast('Máy rửa đã đạt cấp tối đa');if(money<cost)return toast(`Cần ${cost} ₫ để nâng cấp máy rửa`);money-=cost;upgrade++;save();toast('Đã nâng cấp! Phun mạnh hơn, xa hơn.');updateHUD()};$('#sound').onclick=()=>{sound=!sound;$('#sound').textContent=sound?'♫':'♪';if(audio?.state==='suspended')audio.resume()};
