window.addEventListener('keydown',e=>{if(e.target instanceof HTMLElement&&e.target.matches('input,textarea,select,[contenteditable=true]'))return;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();keys[e.key.toLowerCase()]=true; const codeMap={KeyW:'w',KeyA:'a',KeyS:'s',KeyD:'d'};if(codeMap[e.code])keys[codeMap[e.code]]=true;if(e.repeat)return;if(e.key.toLowerCase()==='q')setMode(mode==='fan'?'jet':'fan');if(e.key==='1')setMode('fan');if(e.key==='2')setMode('jet');if(e.key==='Escape')pause();if(e.code==='KeyV'&&active){togglePerspective();return}if(e.code==='Space'&&active&&fishingSpot()&&!driving){fishingAction();return}if(e.code==='KeyE'&&active)interact();if(e.code==='KeyR'&&active)rotateCar()});window.addEventListener('keyup',e=>{keys[e.key.toLowerCase()]=false;const map={KeyW:'w',KeyA:'a',KeyS:'s',KeyD:'d'};if(map[e.code])keys[map[e.code]]=false});window.addEventListener('blur',()=>{spraying=false;Object.keys(keys).forEach(k=>keys[k]=false);if(active)pause()});
