function updateActivities(dt,now){updateFarm(dt);updateLivingWorld(dt,now);updateScoreEffects(dt);updateWaterFX(dt,now);updateVideoStyle(dt,now);if(active){if(spraying){water=Math.max(0,water-dt*1.4);if(water<=0){spraying=false;toast('Hết nước! Đến bồn nước màu xanh và bấm E')}}const walking=!!(keys.w||keys.a||keys.s||keys.d||keys.arrowup||keys.arrowdown||keys.arrowleft||keys.arrowright||moveGoal);walkClock+=dt*(walking?10:1);if(walking){player.position.y=Math.abs(Math.sin(walkClock))*.07;armL.rotation.x=Math.sin(walkClock)*.5;armR.rotation.x=-Math.sin(walkClock)*.5}else{player.position.y=0;armL.rotation.x=0;armR.rotation.x=0}if(spraying){armL.rotation.x=-.8;armR.rotation.x=-1;player.rotation.z=Math.sin(now*.06)*.008}else player.rotation.z=0;updateHose()}for(const o of butterflies){o.b.position.set(-7+Math.sin(now*.0003+o.phase)*6,1.4+Math.sin(now*.001+o.phase)*.5,4+Math.cos(now*.0004+o.phase)*6);o.left.rotation.z=Math.sin(now*.025+o.phase);o.right.rotation.z=-o.left.rotation.z}const remaining=tiles.reduce((s,t)=>s+t.amount,0);document.querySelector('#yardTask').textContent=Math.round((1-remaining/initialDirt)*100)+'%';document.querySelector('#carTask').textContent=Math.round(carClean*100)+'%';document.querySelector('#weedTask').textContent=weeds.filter(w=>w.done).length+'/5';document.querySelector('#waterValue').textContent=Math.ceil(water)+'%';const nearWeed=weeds.some(w=>!w.done&&Math.hypot(w.x-player.position.x,w.z-player.position.z)<1.65),nearTank=player.position.distanceTo(tank.position)<2.2;const ripe=nearestRipeVegetable();hint.textContent=ripe?'E · Thu hoạch '+ripe.kind+' · +20 ₫':nearWeed?'E · Nhổ cỏ dại · +15 ₫':nearTank?'E · Đổ đầy bình nước':'WASD / mũi tên: đi khắp nơi · Chuột phải: đi đến · Chuột trái: phun';hint.style.display=active?'block':'none'}

