function placeJet(m,a,b){const d=b.clone().sub(a);m.position.copy(a).add(b).multiplyScalar(.5);m.scale.set(1,d.length(),1);m.quaternion.setFromUnitVectors(new T.Vector3(0,1,0),d.normalize())}
function updateWaterFX(dt,now){const on=active&&spraying&&pointerValid;jetCore.visible=on;mist.visible=on;sprayStrands.forEach(m=>m.visible=on);if(on){placeJet(jetCore,sprayOrigin,waterImpact);const axis=waterImpact.clone().sub(sprayOrigin).normalize(),side=new T.Vector3().crossVectors(axis,new T.Vector3(0,1,0)).normalize();const width=mode==='fan'?.65:.16;for(let i=0;i<7;i++){const end=waterImpact.clone().addScaledVector(side,(i-3)*width/3);end.y+=Math.sin(now*.04+i)*.03;placeJet(sprayStrands[i],sprayOrigin,end)}mist.position.copy(waterImpact);mist.scale.set(1.6+Math.sin(now*.03)*.1,.45,1.3);for(let j=0;j<14;j++){const i=splashIndex++%splashN;splashP[i*3]=waterImpact.x+(Math.random()-.5)*width;splashP[i*3+1]=waterImpact.y+.03;splashP[i*3+2]=waterImpact.z+(Math.random()-.5)*width;const a=Math.random()*Math.PI*2,speed=1+Math.random()*3;splashV[i].set(Math.cos(a)*speed,1.5+Math.random()*3,Math.sin(a)*speed);splashL[i]=.25+Math.random()*.35}wetClock+=dt;if(waterImpact.y<.3&&wetClock>.12){wetClock=0;const m=new T.Mesh(wetGeo,wetMat);m.rotation.x=-Math.PI/2;m.position.set(waterImpact.x,.181,waterImpact.z);scene.add(m);wetPatches.push(m);if(wetPatches.length>65)scene.remove(wetPatches.shift())}}for(let i=0;i<splashN;i++){if(splashL[i]>0){splashL[i]-=dt;splashV[i].y-=dt*12;splashP[i*3]+=splashV[i].x*dt;splashP[i*3+1]+=splashV[i].y*dt;splashP[i*3+2]+=splashV[i].z*dt;if(splashP[i*3+1]<.2)splashL[i]=0}else splashP[i*3+1]=-100}splashGeo.attributes.position.needsUpdate=true}

