function paintWashedSurface(dest,onCar){if(onCar||dest.y>.4)return;const x=(dest.x+4.345)/10.53*1024,y=(dest.z+4.645)/13.26*1024;if(x<0||x>1024||y<0||y>1024)return;const distance=Math.hypot(x-lastWash.x,y-lastWash.y);if(distance<2)return;lastWash.set(x,y);const r=mode==='fan'?64:30;washCtx.globalCompositeOperation='destination-out';for(let i=0;i<9;i++){const a=i*2.399+sprayPhase,rr=r*(.72+Math.random()*.23),xx=x+Math.cos(a)*r*.44,yy=y+Math.sin(a)*r*.44;const grad=washCtx.createRadialGradient(xx,yy,rr*.65,xx,yy,rr);grad.addColorStop(0,'rgba(0,0,0,.55)');grad.addColorStop(1,'rgba(0,0,0,0)');washCtx.fillStyle=grad;washCtx.beginPath();washCtx.arc(xx,yy,rr,0,7);washCtx.fill()}washTexture.needsUpdate=true}
