function updateVideoStyle(dt,now){sprayPhase+=dt*3;const on=active&&spraying&&pointerValid;foamMesh.visible=on;bubbles.visible=on;arcingJets.forEach(m=>m.visible=on);stream.visible=false;jetCore.visible=false;sprayStrands.forEach(m=>m.visible=false);if(!on)return;const axis=waterImpact.clone().sub(sprayOrigin).normalize(),side=new T.Vector3().crossVectors(axis,new T.Vector3(0,1,0)).normalize(),width=mode==='fan'?.8:.18;for(let i=0;i<6;i++){const end=waterImpact.clone().addScaledVector(side,(i-2.5)*width/2.5),mid=sprayOrigin.clone().lerp(end,.5);mid.y+=.6+Math.sin(now*.015+i)*.035;const curve=new T.QuadraticBezierCurve3(sprayOrigin.clone(),mid,end);const geo=new T.TubeGeometry(curve,16,mode==='fan'?.023:.035,6,false);arcingJets[i].geometry.dispose();arcingJets[i].geometry=geo}foamMesh.position.copy(waterImpact);foamMesh.position.y=Math.max(.205,waterImpact.y+.03);foamMesh.rotation.z=Math.sin(now*.002)*.15;foamMesh.scale.setScalar(mode==='fan'?1:.55);for(let i=0;i<80;i++){const a=i*2.399+now*.001,t=((now*.001+i*.127)%1),r=width*(.35+t*1.2);bubbleObject.position.set(waterImpact.x+Math.cos(a)*r,waterImpact.y+.06+Math.sin(t*Math.PI)*.6,waterImpact.z+Math.sin(a)*r);bubbleObject.scale.setScalar(.7+Math.sin(i*37)*.4);bubbleObject.updateMatrix();bubbles.setMatrixAt(i,bubbleObject.matrix)}bubbles.instanceMatrix.needsUpdate=true}

// Collision follows the car's actual transform, including rotation and scale.
function carLocal(x,z){const dx=x-car.position.x,dz=z-car.position.z,c=Math.cos(car.rotation.y),s=Math.sin(car.rotation.y);return{x:(c*dx-s*dz)/car.scale.x,z:(s*dx+c*dz)/car.scale.z}}
function isCarBlocking(x,z,r=.34){const q=carLocal(x,z),rx=r/car.scale.x,rz=r/car.scale.z;return Math.abs(q.x)<1.43+rx&&Math.abs(q.z)<2.3+rz}
function isWorldBlocking(x,z){const r=.34;if(!inHouse&&!inCity&&hotelInterior===null&&residentialBlocks(x,z))return true;if(!inHouse&&!inCity&&parkBlocks(x,z))return true;if(hotelInterior!==null)return hotelBlocks(x,z);if(!inCity&&!inHouse&&neighborResortBlocks(x,z))return true;if(inHouse){const localX=x-houseX;if(homeFurnitureBlocks(localX,z))return true;if(houseFloor===2&&((localX+2)/3.15)**2+((z+3)/2.15)**2<1&&!(Math.abs(localX+2)<.6&&z>-.9))return true;if(Math.abs(localX)>5.55||z< -6.55||z>7.5)return true;if(z>6.5&&Math.abs(localX)>1.15)return true;return false}if(!inHouse&&!inCity&&(resortPoolBlocks(x,z)||natureBlocks(x,z)))return true;if(x>85){if(Math.hypot(x-120,z)<3.3)return true;return citySolids.some(b=>Math.abs(x-b.x)<b.w&&Math.abs(z-b.z)<b.d)}if(trafficBlocks(x,z)||isCarBlocking(x,z,r))return true;if(x>-4-r&&x<6+r&&z>-11-r&&z<-5+r)return true;if(Math.abs(x+8.5)<.08+r&&((z>-12-r&&z<8.2+r)||(z>10.8-r&&z<11.5+r)))return true;if(Math.abs(x-9.5)<.08+r&&z>-12-r&&z<11.5+r)return true;if(Math.abs(z+12)<.08+r&&x>-8.5-r&&x<9.5+r&&(x<-.4||(x>2.4&&x<6.5)))return true;return false}
function movePlayerWithCollision(dx,dz){if(driving||elevatorRiding||!liftDialog.classList.contains('hidden')||!receptionDialog.classList.contains('hidden')||campusOverview||parkRide||hotelPose||domesticMode||resting||fishingState==='reeling'||fishingState==='holding')return;const count=Math.max(1,Math.ceil(Math.hypot(dx,dz)/.1));for(let i=0;i<count;i++){const x=player.position.x+dx/count;if(!isWorldBlocking(x,player.position.z))player.position.x=x;const z=player.position.z+dz/count;if(!isWorldBlocking(player.position.x,z))player.position.z=z}resolvePlayerCar()}
function resolvePlayerCar(){if(!isCarBlocking(player.position.x,player.position.z))return;const q=carLocal(player.position.x,player.position.z),hx=1.43+.35/car.scale.x,hz=2.3+.35/car.scale.z,c=Math.cos(car.rotation.y),s=Math.sin(car.rotation.y);const options=[[-hx,q.z],[hx,q.z],[q.x,-hz],[q.x,hz]].map(([x,z])=>({x:car.position.x+c*x*car.scale.x+s*z*car.scale.z,z:car.position.z-s*x*car.scale.x+c*z*car.scale.z})).filter(p=>!isWorldBlocking(p.x,p.z)).sort((a,b)=>Math.hypot(a.x-player.position.x,a.z-player.position.z)-Math.hypot(b.x-player.position.x,b.z-player.position.z));if(options.length){player.position.x=options[0].x;player.position.z=options[0].z}}
let catRunTime=0,catWaterCooldown=0;const catDirection=new T.Vector2(0,1);const catFeet=[];for(const x of [-.35,.35])for(const z of [-.17,.17]){const leg=ball(.075,'#ba8652',x,-.06,z,cat,[1,1.8,.8]);catFeet.push(leg)}const catTail=new T.Mesh(new T.TorusGeometry(.28,.045,8,16,Math.PI*1.25),mat('#c38c51'));catTail.position.set(-.65,.2,0);catTail.rotation.x=Math.PI/2;cat.add(catTail);
// Foliage is looked up after the map moves pots to their current positions.
let plantGrowth=[];function resetLivingWorld(){resetVegetables();catRunTime=0;catWaterCooldown=0;cat.position.set(7,.25,6);cat.rotation.set(0,0,0);cat.scale.setScalar(1);plantGrowth=plants.map(pos=>({pos,growth:0,announced:false,leaves:scene.children.filter(m=>m.isMesh&&m.geometry?.type==='SphereGeometry'&&Math.hypot(m.position.x-pos.x,m.position.z-pos.z)<.65&&m.position.y>.6&&m.position.y<1.5).map(mesh=>{if(!mesh.userData.baseLeafScale)mesh.userData.baseLeafScale=mesh.scale.clone();if(!mesh.userData.baseLeafColor)mesh.userData.baseLeafColor=mesh.material.color.clone();mesh.material=mesh.material.clone();mesh.scale.copy(mesh.userData.baseLeafScale);mesh.material.color.copy(mesh.userData.baseLeafColor);return mesh})}));resolvePlayerCar()}
function interactWithWater(dest,dt){waterVegetables(dest,dt);if(Math.hypot(dest.x-cat.position.x,dest.z-cat.position.z)<.85&&catWaterCooldown<=0){catRunTime=2.4;catWaterCooldown=1.4;catDirection.set(cat.position.x-player.position.x,cat.position.z-player.position.z).normalize();if(catDirection.lengthSq()<.1)catDirection.set(-1,1).normalize();toast('Meo! Mèo chạy tránh tia nước 🐈')}for(const plant of plantGrowth){if(Math.hypot(dest.x-plant.pos.x,dest.z-plant.pos.z)>.85)continue;plant.growth=Math.min(1,plant.growth+dt*.45);for(const leaf of plant.leaves){leaf.scale.copy(leaf.userData.baseLeafScale).multiplyScalar(1+plant.growth*.28);leaf.material.color.copy(leaf.userData.baseLeafColor).lerp(new T.Color('#35a14c'),plant.growth)}if(plant.growth>.55&&!plant.announced){plant.announced=true;toast('Cây đã được tưới — lá xanh tốt hơn 🌿')}}}
function updateLivingWorld(dt,now){if(!active)return;catWaterCooldown=Math.max(0,catWaterCooldown-dt);if(catRunTime>0){catRunTime-=dt;const speed=3.2,step=dt*speed;let nx=cat.position.x+catDirection.x*step,nz=cat.position.z+catDirection.y*step;if(nx<-7.7||nx>9||isCarBlocking(nx,cat.position.z,.2)){catDirection.x=-catDirection.x;nx=cat.position.x+catDirection.x*step}if(nz<-3.5||nz>11||isCarBlocking(nx,nz,.2)){catDirection.y=-catDirection.y;nz=cat.position.z+catDirection.y*step}if(!isCarBlocking(nx,nz,.2)){cat.position.x=nx;cat.position.z=nz}cat.rotation.y=Math.atan2(-catDirection.y,catDirection.x);cat.position.y=.29+Math.abs(Math.sin(now*.022))*.09;catFeet.forEach((f,i)=>{f.position.y=-.06+Math.sin(now*.025+i*Math.PI)*.07});catTail.rotation.z=Math.sin(now*.015)*.25}else{cat.position.y=.25;catFeet.forEach(f=>f.position.y=-.06);catTail.rotation.z=Math.sin(now*.002)*.12}}

