function blocksGardenFence(from,to,z){return Math.min(from,to)<-8.05&&Math.max(from,to)>-8.95&&z<8.2}
function nearestRipeVegetable(){return vegetables.filter(c=>c.growth>=1&&Math.hypot(c.group.position.x-player.position.x,c.group.position.z-player.position.z)<1.65).sort((a,b)=>a.group.position.distanceToSquared(player.position)-b.group.position.distanceToSquared(player.position))[0]}
let pendingHarvest=null;
for(const tree of scene.children){if(tree.isGroup&&((tree.position.x===-12&&tree.position.z===4)||(tree.position.x===-11&&tree.position.z===-8)))tree.position.x=-21}
for(const crop of vegetables){const tag=document.createElement('div');tag.className='cropTag';tag.innerHTML='<span></span><small></small><i><b></b></i><button type="button">Thu hoạch +20 ₫</button>';document.body.append(tag);crop.tag=tag;tag.querySelector('button').onclick=()=>{if(!active||crop.growth<1)return;if(!harvestVegetable(crop)){pendingHarvest=crop;moveGoal=crop.group.position.clone();moveGoal.x+=.8;toast('Đang đến thu hoạch '+crop.kind)}}}
