function harvestVegetable(selected){const crop=selected||nearestRipeVegetable();if(!active||!crop||crop.growth<1||crop.group.position.distanceTo(player.position)>1.8)return false;money+=20;save();const v=crop.group.position.clone();v.y=1;v.project(camera);const coin=document.createElement('div');coin.className='cropCoin';coin.textContent='🪙 +20 ₫';coin.style.left=(v.x+1)*innerWidth/2+'px';coin.style.top=(1-v.y)*innerHeight/2+'px';document.body.append(coin);const wallet=$('#money').getBoundingClientRect();const animation=coin.animate([{transform:'translate(0,0) scale(1)',opacity:1},{transform:`translate(${wallet.x-parseFloat(coin.style.left)}px,${wallet.y-parseFloat(coin.style.top)}px) scale(.5)`,opacity:0}],{duration:1000,easing:'ease-in'});animation.onfinish=()=>coin.remove();resetCrop(crop);if(pendingHarvest===crop)pendingHarvest=null;toast('Đã thu hoạch '+crop.kind+' · +20 ₫ · Đã trồng mầm mới');updateHUD();return true}
function resetVegetables(){pendingHarvest=null;$('#cropTask').textContent='0/'+vegetables.length;for(const crop of vegetables)resetCrop(crop)}
