function updateFarm(dt){const closest=vegetables.reduce((best,c)=>!best||c.group.position.distanceToSquared(player.position)<best.group.position.distanceToSquared(player.position)?c:best,null);for(const crop of vegetables){if(active&&crop.moisture>=1&&crop.growth<1){crop.growth=Math.min(1,crop.growth+dt/12);if(crop.growth===1&&!crop.announced){crop.announced=true;toast(crop.kind+' đã chín! Bấm Thu hoạch · +20 ₫')}}const stage=crop.growth>=1?2:crop.growth>=.35?1:0;crop.group.scale.setScalar(stage===2?1.23:stage===1?.7+crop.growth*.25:.35+crop.growth*.4);crop.root.visible=stage>0;for(const leaf of crop.leaves)leaf.material.color.copy(leaf.userData.dryColor).lerp(new T.Color('#45a344'),crop.growth*.6);if(!crop.tag)continue;const near=crop.group.position.distanceTo(player.position)<8&&(crop===closest||crop.moisture>0);crop.tag?.classList.toggle('compact',crop!==closest);if(crop.tag)crop.tag.querySelector('button').textContent=crop===closest?'Thu hoạch +20 ₫':'🧺 +20';const at=crop.group.position.clone();at.y=1.1;at.project(camera);crop.tag.style.display=active&&near&&Math.abs(at.x)<.95&&Math.abs(at.y)<.9?'block':'none';crop.tag.style.left=(at.x+1)*innerWidth/2+'px';crop.tag.style.top=(1-at.y)*innerHeight/2+'px';crop.tag.querySelector('span').textContent=crop.kind+' · '+['Mầm','Đang lớn','Trưởng thành'][stage];crop.tag.querySelector('small').textContent=crop.moisture<1?'💧 Tưới nước '+Math.round((crop.moisture||0)*100)+'%':crop.growth<1?'🌱 '+Math.round(crop.growth*100)+'% · '+Math.ceil((1-crop.growth)*12)+' giây':'✨ Sẵn sàng thu hoạch';crop.tag.querySelector('i b').style.width=((crop.moisture||0)<1?(crop.moisture||0):crop.growth)*100+'%';crop.tag.querySelector('button').style.display=stage===2?'block':'none'}$('#cropTask').textContent=vegetables.filter(c=>c.growth>=1).length+'/'+vegetables.length;if(active&&pendingHarvest&&pendingHarvest.group.position.distanceTo(player.position)<1.7){harvestVegetable(pendingHarvest);moveGoal=null}}


function updateLegacyRoamingCamera(dt){if(driving){updateDrivingCamera(dt);return}if(campusOverview){const destination=new T.Vector3(-18,105,-106);destination.add(mapPan);camera.position.lerp(destination,1-Math.exp(-dt*5));camera.lookAt(-23+mapPan.x,2,24+mapPan.z);camera.updateMatrixWorld();return;}const homeDistrict=neighborhoodView&&!inCity&&!inHouse&&hotelInterior===null&&player.position.x>-45&&player.position.x<28&&player.position.z>-22&&player.position.z<57;const besideResorts=!inCity&&!inHouse&&player.position.z>21&&player.position.x<27;const desiredFocus=new T.Vector3(player.position.x,hotelInterior!==null?1.3:besideResorts?player.position.y+2:player.position.y+.6,player.position.z+(besideResorts?5:-1));if(homeDistrict&&fishingState==='idle')desiredFocus.set(-9+mapPan.x,2,13+mapPan.z);if(!homeDistrict)desiredFocus.add(mapPan);viewFocus.lerp(desiredFocus,1-Math.exp(-dt*10));const offset=angledView?(hotelInterior!==null?(hotelCloseView?new T.Vector3(5,3.5,8):new T.Vector3(8,10,14)):besideResorts?new T.Vector3(14,24,-32):new T.Vector3(inHouse?8:12,inHouse?12:19,inHouse?16:24)):new T.Vector3(0,inHouse?13:inCity?24:31,inHouse?10:inCity?20:8);if(homeDistrict&&fishingState==='idle')offset.set(37,62,-91);if(fishingState!=='idle')offset.set(6,5,8);offset.multiplyScalar(followZoom);const destination=viewFocus.clone().add(offset);camera.position.lerp(destination,1-Math.exp(-dt*10));camera.lookAt(viewFocus);camera.updateMatrixWorld();roamingGround.position.x=Math.round(player.position.x/40)*40;roamingGround.position.z=Math.round(player.position.z/40)*40;const sx=Math.round(player.position.x*4)/4,sz=Math.round(player.position.z*4)/4;sun.position.set(sx-10,18,sz+10);sun.target.position.set(sx,0,sz);sun.target.updateMatrixWorld();if(pointerValid){ray.setFromCamera(pointer,camera);const hit=ray.ray.intersectPlane(groundPlane,new T.Vector3());if(hit)target.copy(hit)}}
