function travelToCity(go){inCity=go;portalCooldown=2;pendingHarvest=null;moveGoal=null;spraying=false;for(const key in keys)keys[key]=false;player.position.set(go?120:-4,0,go?10:11);camera.position.set(player.position.x,31,player.position.z+8);camera.lookAt(player.position.x,0,player.position.z-8);document.body.classList.toggle('inCity',go);scene.fog.color.set(go?'#b4cce6':'#cbdcc4');renderer.setClearColor(go?'#b4cce6':'#cbdcc4');toast(go?'Chào mừng đến thành phố Aurora ✨':'Đã trở về khu vườn');}
function tryPortal(){if(!active||inHouse||portalCooldown>0)return false;const at=inCity?cityPortal.g.position:homePortal.g.position;if(Math.hypot(player.position.x-at.x,player.position.z-at.z)>2.2)return false;travelToCity(!inCity);return true}
function updateDestinations(dt,now){portalCooldown=Math.max(0,portalCooldown-dt);if(closetOpen&&previewRenderer)previewRenderer.render(previewScene,previewCamera);for(const {npc,phase}of citizens){npc.position.set(Math.cos(now*.0001+phase)*6,.02+Math.abs(Math.sin(now*.004+phase))*.035,Math.sin(now*.0001+phase)*9);npc.rotation.y=-now*.0001-phase}fountainWater.rotation.y=Math.sin(now*.0005)*.08;for(const p of [homePortal,cityPortal])p.door.material.opacity=.6+Math.sin(now*.002)*.13;if(active){const at=inCity?cityPortal.g.position:homePortal.g.position;if(Math.hypot(player.position.x-at.x,player.position.z-at.z)<2.2)hint.textContent=inCity?'E · Trở về khu vườn':'E · Đi sang thành phố Aurora';$('.location').textContent=inCity?'✦ AURORA · THÀNH PHỐ ÁNH SÁNG':'☀ VƯỜN NHÀ · BUỔI SÁNG'}}

