const furnitureCatalog=[{id:'sofa',name:'Sofa nhung',cost:60,x:-3,z:-3,w:2.8,d:1.2},{id:'table',name:'Bàn cà phê',cost:30,x:-3,z:-.8,w:1.6,d:1},{id:'bed',name:'Giường êm',cost:100,x:3,z:-3.8,w:2.5,d:3.7},{id:'tv',name:'Kệ TV',cost:80,x:-3,z:2,w:2.5,d:.7},{id:'lamp',name:'Đèn đứng',cost:25,x:4.5,z:2,w:.6,d:.6},{id:'plant',name:'Chậu cây',cost:20,x:3,z:4.5,w:.9,d:.9}];
