const furnitureMeshes={};function makeFurniture(item){const g=new T.Group();room.add(g);const cream=mat('#fff0d9'),oak=mat('#866447'),velvet=mat('#729e91');if(item.id==='sofa'){box(2.8,.5,1.2,velvet,0,.5,0,g);box(2.8,.9,.25,velvet,0,1,-.5,g);for(const x of [-1.25,1.25])box(.25,.65,1.2,velvet,x,.8,0,g);for(const x of [-.65,.65])box(1.1,.15,.8,cream,x,.83,.1,g)}if(item.id==='table'){box(1.6,.12,1,oak,0,.65,0,g);for(const x of [-.65,.65])for(const z of [-.35,.35])box(.1,.6,.1,oak,x,.3,z,g);cyl(.2,.2,.25,'#e8c688',.2,.84,0,g)}if(item.id==='bed'){box(2.5,.4,3.7,oak,0,.35,0,g);box(2.4,.3,3.5,cream,0,.65,0,g);box(2.4,.15,2.3,'#b4a6d5',0,.87,.5,g);for(const x of [-.6,.6])box(.9,.2,.65,'#ffffff',x,.92,-1.1,g);box(2.6,1.2,.2,oak,0,.8,-1.8,g)}if(item.id==='tv'){box(2.5,.55,.7,oak,0,.4,0,g);box(2.2,1.3,.12,'#293941',0,1.4,0,g);box(1.95,1.05,.04,new T.MeshStandardMaterial({color:'#6bb5cf',emissive:'#376f94',emissiveIntensity:.35}),0,1.4,.08,g)}if(item.id==='lamp'){cyl(.3,.3,.08,oak,0,.08,0,g);cyl(.045,.045,2.2,oak,0,1.1,0,g);const shade=new T.Mesh(new T.ConeGeometry(.48,.65,24,1,true),new T.MeshStandardMaterial({color:'#ffdc8b',side:T.DoubleSide,emissive:'#e7ae51',emissiveIntensity:.35}));shade.position.y=2.3;g.add(shade)}if(item.id==='plant'){cyl(.4,.3,.65,'#d39374',0,.33,0,g);for(let i=0;i<7;i++){const a=i*2.4;ball(.3,'#649a65',Math.cos(a)*.25,1+Math.sin(i)*.2,Math.sin(a)*.25,g,[.7,1.3,.7])}}furnitureMeshes[item.id]=g;return g}
