function refreshHouseShop(){homeShop.querySelector('#homeBalance').textContent='Ví của bạn: '+money+' ₫';const cards=homeShop.querySelector('#furnitureCards');cards.innerHTML='';for(const item of furnitureCatalog){const card=document.createElement('article'),owned=!!houseItems[item.id];card.innerHTML='<b>'+item.name+'</b><small>'+(owned?'Đã sở hữu':item.cost+' ₫')+' · '+['Tầng 1','Tầng 2','Sân chơi'][item.floor||0]+'</small>';const buy=document.createElement('button');buy.textContent=owned?'Đổi vị trí':'Mua '+item.name+' · '+item.cost+' ₫';buy.onclick=()=>{if(!inHouse)return;if(!houseItems[item.id]){if(money<item.cost){toast('Bạn cần '+item.cost+' ₫ để mua '+item.name);return}money-=item.cost;save();houseItems[item.id]={x:item.x,z:item.z,rotation:0,floor:item.floor||0};const mesh=furnitureMeshes[item.id];mesh.visible=true;mesh.position.set(item.x,0,item.z);saveHouse();updateHUD();toast('Đã mua '+item.name+' · Đặt ở '+['tầng 1','tầng 2','sân chơi'][item.floor||0])}else{if(houseFloor!==(item.floor||0)){changeHouseFloor(item.floor||0)}placingFurniture=item.id;homeShop.classList.add('hidden');toast('Bấm xuống sàn để đặt '+item.name)}refreshHouseShop()};card.append(buy);if(owned){const rotate=document.createElement('button');rotate.textContent='Xoay '+item.name;rotate.onclick=()=>{houseItems[item.id].rotation+=Math.PI/2;furnitureMeshes[item.id].rotation.y=houseItems[item.id].rotation;saveHouse();toast('Đã xoay '+item.name)};card.append(rotate)}cards.append(card)}}
furnitureButton.onclick=()=>{if(!inHouse||!active)return;spraying=false;refreshHouseShop();homeShop.classList.remove('hidden')};homeShop.querySelector('[aria-label="Đóng cửa hàng nội thất"]').onclick=()=>homeShop.classList.add('hidden');
function handleFurniturePlacement(){if(!inHouse||!placingFurniture)return false;const item=furnitureCatalog.find(c=>c.id===placingFurniture),x=target.x-houseX,z=target.z;const slot=houseItems[item.id],turned=Math.abs(Math.sin(slot.rotation))>.5,halfW=(turned?item.d:item.w)/2,halfD=(turned?item.w:item.d)/2;if(Math.abs(x)>5.7-halfW||Math.abs(z)>6.6-halfD||(Math.abs(x)<1.5&&z>4.8)){toast('Hãy đặt đồ trong phòng và chừa lối cửa');return true}for(const other of furnitureCatalog){const at=houseItems[other.id];if(!at||other.id===item.id||(other.floor||0)!==houseFloor)continue;const rotated=Math.abs(Math.sin(at.rotation))>.5;if(Math.abs(x-at.x)<halfW+(rotated?other.d:other.w)/2&&Math.abs(z-at.z)<halfD+(rotated?other.w:other.d)/2){toast('Vị trí này đang có đồ nội thất');return true}}slot.x=x;slot.z=z;furnitureMeshes[item.id].position.set(x,0,z);saveHouse();placingFurniture=null;toast('Đã đặt '+item.name);return true}
function enterHouse(enter){if(enter&&!enteringResidentialHouse)visitingHouseSlot=0;inHouse=enter;houseFloor=0;updateHouseLevels();roomTravelCooldown=2;houseCooldown=2;portalCooldown=2;spraying=false;placingFurniture=null;moveGoal=null;pendingHarvest=null;for(const key in keys)keys[key]=false;player.position.set(enter?houseX:1,0,enter?4.2:-2.5);document.body.classList.toggle('inHouse',enter);homeShop.classList.add('hidden');camera.position.set(player.position.x,enter?13:31,player.position.z+(enter?10:8));camera.lookAt(player.position.x,0,player.position.z-2);if(!enter&&visitingHouseSlot>0){const plot=housePlots[visitingHouseSlot];player.position.set(plot.x,0,plot.z+5)}toast(enter?'Chào mừng về nhà! Bấm Nội thất để mua đồ.':'Đã ra sân nhà')}
function updateHouse(dt){houseCooldown=Math.max(0,houseCooldown-dt);if(!active||closetOpen)return;if(inHouse){$('.location').textContent='⌂ NHÀ CỦA BẠN';hint.textContent=placingFurniture?'Bấm sàn để đặt nội thất':'🛋 Bấm Nội thất để mua và trang trí · Đi ra cửa để về sân';if(houseFloor===0&&houseCooldown===0&&Math.abs(player.position.x-houseX)<1.2&&player.position.z>6)enterHouse(false)}else if(!inCity&&houseCooldown===0&&Math.abs(player.position.x-1)<.75&&player.position.z<-3.65&&player.position.z>-5)enterHouse(true);if(portalCooldown===0&&!inHouse){const portal=inCity?cityPortal.g.position:homePortal.g.position;if(Math.hypot(player.position.x-portal.x,player.position.z-portal.z)<.85)travelToCity(!inCity)}}

