furnitureCatalog.push({id:'aquarium',name:'Bể cá cảnh',cost:90,x:2,z:-2,w:2.4,d:1,floor:0},{id:'dining',name:'Bàn ăn gia đình',cost:70,x:2,z:1.3,w:2.8,d:2,floor:0},{id:'wardrobe',name:'Tủ phòng ngủ',cost:80,x:-4,z:-5.2,w:2.2,d:.8,floor:1},{id:'desk',name:'Bàn học',cost:45,x:-3,z:1,w:2,d:1,floor:1},{id:'swing',name:'Xích đu sân chơi',cost:65,x:-2,z:-2,w:2.8,d:2,floor:2},{id:'slide',name:'Cầu trượt',cost:75,x:2.6,z:-2,w:2,d:3,floor:2});
function addLifeFurniture(item){const g=new T.Group();const parent=item.floor===1?upstairsRoom:item.floor===2?gardenRoom:room;parent.add(g);if(item.id==='aquarium'){box(2.4,.65,1,'#987454',0,.33,0,g);const tankMat=new T.MeshStandardMaterial({color:'#73d4e5',transparent:true,opacity:.28,roughness:.15,depthWrite:false});box(2.35,1.2,.95,tankMat,0,1.3,0,g);box(2.4,.08,1,'#405b62',0,1.92,0,g);box(2.3,.08,.9,'#e8cf98',0,.72,0,g);for(let j=0;j<5;j++){const fish=new T.Group();g.add(fish);ball(.12,j%2?'#f1a451':'#83b1e8',0,0,0,fish,[1.5,.75,.5]);const tail=new T.Mesh(new T.ConeGeometry(.1,.16,3),mat('#f6c66e'));tail.rotation.z=Math.PI/2;tail.position.x=-.23;fish.add(tail);fishSchool.push({fish,phase:j*1.3})}for(const x of [-.8,.8])for(let j=0;j<3;j++)ball(.08,'#5aab79',x+j*.06,.9+j*.1,0,g,[.5,2,1])}if(item.id==='dining'||item.id==='desk'){box(item.id==='desk'?2:2.1,.12,1,'#ad805b',0,.9,0,g);for(const x of [-.8,.8])for(const z of [-.35,.35])box(.08,.85,.08,'#876348',x,.43,z,g);for(const x of item.id==='desk'?[0]:[-.65,.65])for(const z of item.id==='desk'?[.85]:[-.85,.85]){box(.55,.12,.5,'#6e9b95',x,.52,z,g);box(.55,.65,.08,'#6e9b95',x,.85,z+(z>0?.25:-.25),g);for(const dx of [-.2,.2])box(.06,.5,.06,'#876348',x+dx,.25,z,g)}}if(item.id==='wardrobe'){box(2.2,2.6,.8,'#c49d76',0,1.3,0,g);for(const x of [-.55,.55]){box(1,.02,.04,'#f5dfb8',x,2.5,.43,g);box(.04,.25,.05,'#72583d',x/4,1.3,.44,g)}}if(item.id==='swing'){for(const x of [-1.2,1.2])box(.12,2.8,.15,'#bd8b60',x,1.4,0,g);box(2.7,.15,.16,'#bd8b60',0,2.75,0,g);const seat=new T.Group();seat.position.y=2.65;g.add(seat);for(const x of [-.4,.4])cyl(.018,.018,1.8,'#eee1bc',x,-.9,0,seat);box(1.1,.12,.5,'#dd9d75',0,-1.8,0,seat);swingSeats.push(seat)}if(item.id==='slide'){box(1.4,1.6,1,'#f0bd70',0,.8,-.8,g);const ramp=box(1.3,.1,2.7,'#81c1ce',0,.85,.65,g);ramp.rotation.x=.5;for(const x of [-.75,.75])box(.09,.65,1.1,'#cf8d67',x,1.9,-.8,g)}furnitureMeshes[item.id]=g;return g}
for(const item of furnitureCatalog){let mesh=furnitureMeshes[item.id];if(!mesh)mesh=addLifeFurniture(item);const floor=item.floor||0;const parent=floor===1?upstairsRoom:floor===2?gardenRoom:room;if(mesh.parent!==parent)parent.add(mesh);let saved=houseItems[item.id];if(!saved){try{const raw=JSON.parse(localStorage.getItem('garden-home')||'{}')[item.id];if(raw&&Number.isFinite(raw.x)&&Number.isFinite(raw.z))saved=houseItems[item.id]={x:raw.x,z:raw.z,rotation:raw.rotation||0,floor}}catch{}}if(saved){saved.floor=floor;if(item.id==='bed'&&saved.x>0){saved.x=item.x;saved.z=item.z}mesh.position.set(saved.x,0,saved.z);mesh.rotation.y=saved.rotation||0}mesh.visible=!!saved}saveHouse();
function updateHouseLevels(){room.visible=inHouse&&houseFloor===0;upstairsRoom.visible=inHouse&&houseFloor===1;gardenRoom.visible=inHouse&&houseFloor===2;for(const item of furnitureCatalog){const owned=houseItems[item.id];if(owned)furnitureMeshes[item.id].visible=true}}
function changeHouseFloor(next){houseFloor=next;roomTravelCooldown=2;houseCooldown=2;placingFurniture=null;moveGoal=null;spraying=false;for(const key in keys)keys[key]=false;homeShop.classList.add('hidden');player.position.set(houseX+(next===2?3:next===1?4.5:3),0,next===2?4.5:1.3);updateHouseLevels();toast(next===1?'Tầng 2 · Phòng ngủ & phòng tắm':next===2?'Sân chơi sau nhà':'Tầng 1 · Phòng khách & bếp')}
function updateHouseLife(dt,now){roomTravelCooldown=Math.max(0,roomTravelCooldown-dt);for(const {fish,phase}of fishSchool){fish.position.set(Math.sin(now*.0007+phase)*.8,1.3+Math.cos(now*.001+phase)*.2,Math.cos(now*.0005+phase)*.22);fish.rotation.y=Math.cos(now*.0007+phase)>0?0:Math.PI}for(const seat of swingSeats)seat.rotation.x=Math.sin(now*.0015)*.2;if(!inHouse)return;const x=player.position.x-houseX,z=player.position.z;$('.location').textContent=['⌂ TẦNG 1 · PHÒNG KHÁCH & BẾP','⌂ TẦNG 2 · PHÒNG NGỦ & PHÒNG TẮM','☀ SÂN CHƠI SAU NHÀ'][houseFloor];if(!active||closetOpen||roomTravelCooldown>0)return;if(houseFloor===0){if(x>3.7&&z>3.5&&z<5.8)changeHouseFloor(1);else if(x< -4.5&&z>2&&z<4.3)changeHouseFloor(2)}else if(houseFloor===1&&x>3.7&&z>3.5&&z<5.8)changeHouseFloor(0);else if(houseFloor===2&&x>4&&z>3.8)changeHouseFloor(0)}
