const hotelMenu=document.createElement('div');hotelMenu.style.cssText='position:fixed;right:20px;top:160px;z-index:25;display:none;max-width:230px;background:#fff7e8ed;border:1px solid #bfa46d;border-radius:14px;padding:14px;color:#304b48;font:13px sans-serif;box-shadow:0 12px 40px #152c3030';document.body.append(hotelMenu);const hotelTitle=document.createElement('strong');hotelMenu.append(hotelTitle);const hotelInfo=document.createElement('p');hotelMenu.append(hotelInfo);const hotelActions=document.createElement('div');hotelMenu.append(hotelActions);
function hotelButton(text,fn){const b=document.createElement('button');b.textContent=text;b.style.cssText='display:block;margin-top:8px;width:100%;padding:10px;border:0;border-radius:7px;background:#365d59;color:#fff4d9;cursor:pointer';b.onclick=fn;hotelActions.append(b)}
function refreshHotelMenu(){hotelActions.replaceChildren();if(hotelInterior===null){hotelTitle.textContent='KHU KHÁCH SẠN · 6 ĐIỂM ĐẾN';hotelInfo.textContent='Chọn khách sạn để đến trước sảnh.';hotelSpecs.forEach((h,i)=>hotelButton(h.name,()=>{player.position.set(120+h.x,0,h.z+7.7);moveGoal=null;hotelCooldown=1;toast(h.name+' · Đi thẳng vào cửa')}))}else{hotelTitle.textContent=neighborReturn?neighborSites.find(s=>s.index===hotelInterior)?.name:hotelSpecs[hotelInterior].name;hotelInfo.textContent=hotelSpecs[hotelInterior].style+' · '+{lobby:'Sảnh lễ tân',suite:'Phòng suite',pool:'Hồ bơi',dining:'Nhà hàng',spa:'Spa thư giãn',corridor:'Hành lang tầng '+hotelFloorNumber}[hotelArea];hotelButton('🔑 Thông tin phòng & thẻ khóa',()=>showRoomCard());hotelButton('👩 Lễ tân đi cùng giúp tôi',()=>startReceptionEscort('follow'));hotelButton('🛗 Nhờ dẫn tới thang máy',()=>startReceptionEscort('guide'));hotelButton('🖐 Cảm ơn, tôi tự đi',()=>stopReceptionEscort());hotelButton('🌴 Hồ bơi & spa',()=>changeHotelArea('pool'));if(hotelInterior===4){hotelButton('🍽 Nhà hàng',()=>changeHotelArea('dining'));hotelButton('🌿 Spa',()=>changeHotelArea('spa'));}hotelButton('🚪 Ra thành phố',()=>leaveHotel())}}
function changeHotelArea(area){stopHotelPose();hotelArea=area;selectHotelInteriors();for(const [id,g]of Object.entries(hotelFloors))g.visible=id===area;player.position.set(hotelBase,0,7);moveGoal=null;hotelCooldown=2;ensureHotelRoutes();refreshHotelMenu()}
function enterHotel(i){hotelInterior=i;hotelArea='lobby';changeHotelArea('lobby');greetingUntil=performance.now()+7000;toast('Chào mừng đến '+hotelSpecs[i].name+' · Gặp lễ tân để nhận phòng')}
function leaveHotel(){if(hotelInterior===null)return;if(neighborReturn){leaveNeighborResort();return;}const h=hotelSpecs[hotelInterior];stopHotelPose();hotelInterior=null;for(const g of Object.values(hotelFloors))g.visible=false;player.position.set(120+h.x,0,h.z+7.7);moveGoal=null;hotelCooldown=2;refreshHotelMenu();toast('Đã trở lại đại lộ khách sạn')}
function hotelBlocks(x,z){const lx=x-hotelBase;if(hotelArea==='corridor')return corridorBlocks(lx,z);if(hotelArea==='lobby'&&lx>-6&&lx< -3&&z< -5.1)return z< -8.4||!elevatorOpen;if(hotelInterior===4&&hotelArea==='dining')return Math.abs(lx)>8.5||z< -9.5||z>10||bayDiningTables.some(p=>Math.abs(lx-p.x)<1.6&&Math.abs(z-p.z)<1.45);if(hotelInterior===4&&hotelArea==='spa')return Math.abs(lx)>8.5||z< -9.5||z>10||[-4,4].some(a=>Math.abs(lx-a)<1.4&&Math.abs(z+3)<2);if(hotelArea==='suite'&&lx>=8.5&&lx<11.3&&z>-2.3&&z<4.3)return false;if(hotelArea==='lobby'&&Math.abs(z+5)<.65&&[-6.7,0,6.7].some(a=>Math.abs(lx-a)<.6))return true;if(hotelArea==='suite'&&Math.abs(lx-3.5)<1.25&&Math.abs(z-6)<1)return true;if(Math.abs(lx)>8.5||z< -9.5||z>10)return true;if(z>8.8&&Math.abs(lx)>1.5)return true;if(hotelArea==='pool')return lx>-6.4&&lx<2.4&&z>-6.5&&z<4.5;if(hotelArea==='suite')return(Math.abs(lx+3)<1.8&&Math.abs(z+4)<2.5)||(lx>2.6&&lx<5.4&&z>.1&&z<1.9)||(lx>2.6&&lx<5.4&&z>2.1&&z<3.9)||(lx>2.5&&lx<7.5&&z< -5&&z>-8)||(lx<-5.5&&z<-6);return(Math.abs(lx+4)<2.1&&Math.abs(z+2)<1.15)||(Math.abs(lx+4)<1.4&&Math.abs(z-.3)<1)||(Math.abs(lx-4)<2.1&&Math.abs(z-2)<1.15)||(lx>1&&lx<7&&z< -5.4&&z>-7.5)}
function hotelNearbySeat(){if(hotelInterior===null||hotelArea==='pool'||hotelArea==='corridor')return null;const seats=hotelArea==='spa'?[{x:-4,z:-3,type:'bed'},{x:4,z:-3,type:'bed'}]:hotelArea==='dining'?bayDiningTables.map(p=>({x:p.x,z:p.z+1.3,type:'sofa'})):hotelArea==='suite'?[{x:-3,z:-4,type:'bed'},{x:4,z:1,type:'sofa'}]:[{x:-4,z:-2,type:'sofa'},{x:4,z:2,type:'sofa'}];return seats.find(a=>Math.hypot(player.position.x-hotelBase-a.x,player.position.z-a.z)<2.8)}
function stopHotelPose(){if(!hotelPose)return;player.position.copy(hotelOrigin);player.rotation.x=player.rotation.z=0;legs.forEach(l=>l.rotation.x=0);restingGear.forEach(o=>o.visible=true);hotelPose=null;for(const k in keys)keys[k]=false}
function hotelAction(){if(hotelInterior===null)return false;if(hotelPhysicalAction())return true;if(hotelPose){stopHotelPose();return true}const seat=hotelNearbySeat();if(!seat)return false;hotelOrigin.copy(player.position);hotelPose=seat;restingGear.forEach(o=>o.visible=false);moveGoal=null;for(const k in keys)keys[k]=false;return true}
