function parkNearby(){if(inCity||inHouse||hotelInterior!==null)return null;if(Math.hypot(player.position.x+75,player.position.z-27)<3)return 'ferris';if(Math.hypot(player.position.x+55,player.position.z-27)<3)return 'carousel';if(Math.hypot(player.position.x+79,player.position.z-40)<2.8)return 'coaster';return null}
