function parkAction(){if(parkRide){stopParkRide();return true}const ride=parkNearby();if(!ride)return false;parkOrigin.copy(player.position);parkRide=ride;parkRideTimer=0;restingGear.forEach(o=>o.visible=false);moveGoal=null;spraying=false;for(const k in keys)keys[k]=false;toast(ride==='ferris'?'Bắt đầu ngắm cảnh trên vòng quay':ride==='coaster'?'Bắt đầu chuyến tàu lượn':'Bắt đầu vòng quay ngựa gỗ');return true}
