function washerEquipped(){return !driving&&!inCity&&!inHouse&&hotelInterior===null&&!resting&&!domesticMode&&!parkRide&&fishingState==='idle'&&player.position.x>-9&&player.position.x<10&&player.position.z>-12&&player.position.z<12}function updatePremiumUI(){player.visible=!driving&&!walkFirstPerson;const equipped=washerEquipped();restingGear.forEach(o=>o.visible=equipped);gun.visible=equipped;if(hose)hose.visible=equipped;document.body.classList.toggle('insideHotel',hotelInterior!==null);hotelViewButton.style.display=active&&hotelInterior!==null?'block':'none';hotelMenu.style.top=hotelInterior!==null?'90px':'160px'}

