const onlineRoom=(new URLSearchParams(location.search).get('room')||'khu-pho-minhzau').replace(/[^a-zA-Z0-9_-]/g,'').slice(0,48)||'khu-pho-minhzau';
const onlineId=crypto.randomUUID(),onlinePeers=new Map(),onlineStates=new Map();let onlinePeer=null,onlineHost=false,onlineConnection=null,onlineStarted=false;
const onlinePanel=document.createElement('div');Object.assign(onlinePanel.style,{position:'fixed',left:'18px',bottom:'115px',zIndex:25,background:'#f8faee',padding:'10px',borderRadius:'14px',color:'#294b40',maxWidth:'235px',fontSize:'12px'});
const onlineStatus=document.createElement('div');onlineStatus.textContent='👥 Đang chuẩn bị phòng chơi chung…';const onlineName=document.createElement('input');onlineName.placeholder='Tên của bạn';onlineName.maxLength=20;onlineName.value=localStorage.getItem('garden-guest-name')||'Khách '+onlineId.slice(0,4);onlineName.setAttribute('aria-label','Tên chơi chung');onlineName.onchange=()=>localStorage.setItem('garden-guest-name',onlineName.value.slice(0,20));const onlineShare=document.createElement('button');onlineShare.textContent='🔗 Sao chép link mời bạn';onlineShare.onclick=async()=>{const u=new URL(location.href);u.searchParams.set('room',onlineRoom);try{await navigator.clipboard.writeText(u.href);toast('Đã sao chép link phòng · Gửi bạn bè để chơi chung')}catch{toast(u.href)}};onlinePanel.append(onlineStatus,onlineName,onlineShare);document.body.append(onlinePanel);
function onlineLocation(){return hotelInterior!==null?'hotel-'+hotelInterior+'-'+hotelArea+(hotelArea==='corridor'?'-'+hotelFloorNumber:''):inHouse?'house-'+visitingHouseSlot+'-'+houseFloor:inCity?'city':'outdoor'}
function onlineLocal(){return {car:driving?{x:sportCar.position.x,z:sportCar.position.z,r:sportCar.rotation.y}:null,house:myHouseSlot,id:onlineId,name:onlineName.value.slice(0,20),x:player.position.x,y:player.position.y,z:player.position.z,r:player.rotation.y,where:onlineLocation(),active}}
function onlineReceive(v){if(!v||typeof v.id!=='string'||v.id===onlineId||v.id.length>80||![v.x,v.y,v.z,v.r].every(Number.isFinite)||Math.abs(v.x)>1000||Math.abs(v.z)>1000)return;onlineStates.set(v.id,{...v,name:String(v.name||'Khách').slice(0,20),seen:performance.now()});}
function onlineWire(c){c.on('data',msg=>{if(onlineHost){if(msg?.type==='state'&&msg.state){if(!houseAssignments.has(msg.state.id)){const used=new Set(houseAssignments.values());const slot=[0,1,2,3,4,5].find(n=>!used.has(n));if(slot===undefined){c.send({type:'full'});return}houseAssignments.set(msg.state.id,slot)}msg.state.house=houseAssignments.get(msg.state.id);onlineReceive(msg.state);c.gardenId=msg.state.id}}else if(msg?.type==='world'&&Array.isArray(msg.states)){if(Number.isInteger(msg.slots?.[onlineId]))assignMyHouse(msg.slots[onlineId]);msg.states.slice(0,6).forEach(onlineReceive)}else if(msg?.type==='full')onlineStatus.textContent='Phòng đã đủ 6 nhà · Dùng link phòng khác để chơi';});c.on('close',()=>{if(c.gardenId){onlineStates.delete(c.gardenId);houseAssignments.delete(c.gardenId)}if(!onlineHost){onlineStatus.textContent='Chủ phòng đã rời · Đang kết nối lại…';setTimeout(onlineStart,2000)}});c.on('error',()=>{});}
function onlineStart(){if(onlinePeer)onlinePeer.destroy();onlineStarted=true;onlineHost=false;onlineConnection=null;onlineStates.clear();const hostId='san-nha-v42-'+onlineRoom;onlinePeer=new window.Peer(hostId,{debug:0});onlinePeer.on('open',()=>{onlineHost=true;houseAssignments.set(onlineId,0);assignMyHouse(0);onlineStatus.textContent='👥 Phòng sẵn sàng · Gửi link để mời bạn'});onlinePeer.on('connection',c=>{onlineWire(c)});onlinePeer.on('error',err=>{if(err.type==='unavailable-id'){onlinePeer.destroy();onlinePeer=new window.Peer(undefined,{debug:0});onlinePeer.on('open',()=>{onlineConnection=onlinePeer.connect(hostId,{reliable:true});onlineWire(onlineConnection);onlineConnection.on('open',()=>onlineStatus.textContent='👥 Đã vào phòng chung');});onlinePeer.on('error',()=>onlineStatus.textContent='Chưa kết nối được phòng · Thử tải lại');}else onlineStatus.textContent='Chưa kết nối được phòng · Bạn vẫn chơi riêng được';});}
function onlineAvatar(id){const g=player.clone(true);g.name='online-guest-'+id;for(const gear of restingGear){const index=player.children.indexOf(gear);if(g.children[index])g.children[index].visible=false}const cv=document.createElement('canvas');cv.width=256;cv.height=64;const cx=cv.getContext('2d');const tex=new T.CanvasTexture(cv);const label=new T.Sprite(new T.SpriteMaterial({map:tex,depthTest:false}));label.position.y=3;label.scale.set(2.5,.625,1);g.add(label);scene.add(g);const obj={g,cv,cx,tex,label,name:''};onlinePeers.set(id,obj);return obj;}
function updateOnline(){const now=performance.now();for(const[id,v]of onlineStates){if(now-v.seen>4500){onlineStates.delete(id);continue}const o=onlinePeers.get(id)||onlineAvatar(id);o.g.visible=!!v.active&&!v.car&&v.where===onlineLocation();o.g.position.lerp(new T.Vector3(v.x,v.y,v.z),.28);o.g.rotation.set(0,v.r,0);if(o.name!==v.name){o.name=v.name;o.cx.clearRect(0,0,256,64);o.cx.fillStyle='#244c40';o.cx.fillRect(0,0,256,64);o.cx.fillStyle='#fff';o.cx.font='26px sans-serif';o.cx.textAlign='center';o.cx.fillText(v.name,128,43);o.tex.needsUpdate=true}}for(const[id,o]of onlinePeers)if(!onlineStates.has(id)){scene.remove(o.g);o.tex.dispose();o.label.material.dispose();onlinePeers.delete(id)}}
setInterval(()=>{if(!onlineStarted)return;const state=onlineLocal();if(onlineHost){const packet={type:'world',slots:Object.fromEntries(houseAssignments),states:[state,...onlineStates.values()].map(({seen,...v})=>v)};for(const list of Object.values(onlinePeer.connections||{}))for(const c of list)if(c.open)c.send(packet)}else if(onlineConnection?.open)onlineConnection.send({type:'state',state});if(onlineHost||onlineConnection?.open)onlineStatus.textContent='👥 '+(onlineStates.size+1)+' người · '+onlineRoom;},120);
window.addEventListener('pagehide',()=>onlinePeer?.destroy());

