function signalFishBite(){if(sound&&audio){try{const osc=audio.createOscillator(),gain=audio.createGain();osc.connect(gain);gain.connect(audio.destination);osc.frequency.setValueAtTime(740,audio.currentTime);osc.frequency.exponentialRampToValueAtTime(1100,audio.currentTime+.12);gain.gain.setValueAtTime(.12,audio.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.3);osc.start();osc.stop(audio.currentTime+.3)}catch{}}}
function updateFishingFeedback(now){const bite=active&&fishingState==='bite';biteAlert.style.display=bite?'block':'none';if(bite){const screen=player.position.clone().add(new T.Vector3(0,3.5,0)).project(camera);biteAlert.style.left=((screen.x+1)*innerWidth/2-15)+'px';biteAlert.style.top=((-screen.y+1)*innerHeight/2-45)+'px';biteAlert.style.transform='scale('+(1+Math.sin(now*.025)*.12)+')'}rodTip.visible=fishingState==='reeling';if(active&&fishingState==='reeling'&&catchAnimation<.5){camera.position.x+=Math.sin(now*.11)*.065*(1-catchAnimation/.5);camera.position.y+=Math.cos(now*.09)*.04;camera.updateMatrixWorld()}}


