const receptionDialog=document.createElement('div');receptionDialog.className='overlay hidden';receptionDialog.style.zIndex=110;const receptionCard=document.createElement('section');const receptionTitle=document.createElement('h2'),receptionText=document.createElement('p'),bookButton=document.createElement('button'),closeReception=document.createElement('button');bookButton.className='primary';bookButton.textContent='Nhận phòng · Miễn phí trong game';closeReception.textContent='Để sau';closeReception.style.cssText='margin-top:14px;padding:12px;border-radius:10px;width:100%';receptionCard.append(receptionTitle,receptionText,bookButton,closeReception);receptionDialog.append(receptionCard);document.body.append(receptionDialog);closeReception.onclick=()=>receptionDialog.classList.add('hidden');
function openReception(){if(hotelInterior===null)return;for(const k in keys)keys[k]=false;moveGoal=null;spraying=false;if(hotelArea!=='lobby')changeHotelArea('lobby');receptionTitle.textContent='👩 Lễ tân Linh · '+(neighborReturn?neighborSites.find(v=>v.index===hotelInterior)?.name:hotelSpecs[hotelInterior].name);const booking=hotelBookings[hotelInterior];receptionText.textContent=booking?'Chào mừng quý khách trở lại! Phòng '+booking+' đã sẵn sàng. Bạn có thể lên phòng, dùng hồ bơi hoặc dạo quanh khách sạn.':'Em là Linh, lễ tân khách sạn. Em sẽ đi cùng hỗ trợ anh/chị nhận phòng nhé! Phòng Ocean Suite · 48 m² · 1 giường đôi · ban công nhìn biển · bồn tắm · hồ bơi. Phòng '+(hotelInterior+2)+'08, tầng '+(hotelInterior+2)+'. Nhận thẻ tại đây rồi đi thang máy bên trái sảnh. Nhận phòng miễn phí trong game.';bookButton.textContent=booking?'Xem thẻ phòng · Đến thang máy':'Nhận phòng · Lấy thẻ khóa';receptionDialog.classList.remove('hidden')}
