const receptionistGroups=new Set();
function makeAoDaiReceptionist(){const npc=new T.Group();npc.name='hotel-receptionist';const silk=new T.MeshStandardMaterial({color:'#b83862',roughness:.48}),trim=new T.MeshStandardMaterial({color:'#e9bb74',metalness:.3,roughness:.45}),skin=mat('#f1c4a7'),hair=mat('#30252a'),white=mat('#f7f1e6');
ball(.29,silk,0,1.28,0,npc,[1,1.4,.7]);cyl(.115,.12,.12,silk,0,1.68,0,npc);for(const z of[-.14,.14]){const panel=new T.Mesh(new T.CylinderGeometry(.24,.38,.95,24,1,true,0,Math.PI*2),silk);panel.scale.z=.22;panel.position.set(0,.65,z);npc.add(panel);for(let i=0;i<8;i++){const x=Math.sin(i*1.9)*.16,y=.28+i*.13;ball(.024,trim,x,y,z+(z>0?.065:-.065),npc,[1,.8,.35])}}
for(const x of[-.15,.15]){cyl(.095,.15,.85,white,x,.51,0,npc);ball(.095,'#55424d',x,.09,.08,npc,[.8,.6,1.6])}ball(.29,skin,0,1.97,.025,npc,[.85,1,.86]);ball(.3,hair,0,2.12,-.04,npc,[.9,.52,.9]);ball(.14,hair,0,2.02,-.28,npc);for(const x of[-.12,.12]){ball(.055,'#fff8ec',x,2.0,.25,npc,[1,.65,.22]);ball(.03,'#35272e',x,2,.267,npc);const brow=ball(.065,hair,x,2.09,.244,npc,[1,.16,.15]);brow.rotation.z=x>0?-.1:.1;ball(.035,'#df8d96',x*1.5,1.88,.21,npc,[1,.5,.2])}ball(.035,skin,0,1.93,.276,npc);const smile=new T.Mesh(new T.TorusGeometry(.055,.009,8,20,Math.PI),mat('#a95165'));smile.rotation.z=Math.PI;smile.position.set(0,1.85,.257);npc.add(smile);
const arms=[];for(const x of[-.31,.31]){const arm=new T.Group();arm.position.set(x,1.49,0);npc.add(arm);const sleeve=cyl(.075,.09,.55,silk,0,-.24,0,arm);ball(.065,skin,0,-.55,0,arm);arm.rotation.z=x>0?-.16:.16;arms.push(arm)}npc.userData.arms=arms;box(.12,.06,.018,trim,.14,1.49,.19,npc);for(let i=0;i<5;i++)ball(.013,trim,.08,1.62-i*.1,.2,npc);npc.scale.setScalar(1.1);return npc}
function addReceptionist(lobby){if(receptionistGroups.has(lobby))return;receptionistGroups.add(lobby);for(const g of lobby.children)if(g.isGroup&&g.children.length===4&&Math.abs(g.position.x-4)<.01&&g.position.z< -7)g.visible=false;const npc=makeAoDaiReceptionist();npc.position.set(.7,0,-7.8);lobby.add(npc);hotelSign('LỄ TÂN LINH · CHECK-IN',4,2.9,-7.5,lobby,3.5)}

function updateHotelAccess(now){nearbyHotelEntry=null;if(active&&!inHouse&&hotelInterior===null&&!parkRide){if(!inCity){for(const site of neighborSites)if(Math.hypot(player.position.x-site.entryX,player.position.z-site.entryZ)<4.5){nearbyHotelEntry={site};break}}else for(let i=0;i<hotelSpecs.length;i++){const h=hotelSpecs[i];if(Math.hypot(player.position.x-120-h.x,player.position.z-h.z-6.1)<4.5){nearbyHotelEntry={index:i};break}}}hotelEntry.style.display=nearbyHotelEntry?'block':'none';hotelEntry.textContent=nearbyHotelEntry?'🚪 Vào '+(nearbyHotelEntry.site?.name||hotelSpecs[nearbyHotelEntry.index].name):'';if(hotelInterior!==null&&hotelFloors.lobby)addReceptionist(hotelFloors.lobby)}
