function routePlaque(text,x,y,z,parent,w=1.4){const cv=document.createElement('canvas');cv.width=512;cv.height=128;const ctx=cv.getContext('2d'),texture=new T.CanvasTexture(cv);const m=new T.Mesh(new T.PlaneGeometry(w,w/4),new T.MeshBasicMaterial({map:texture}));m.position.set(x,y,z);parent.add(m);const redraw=t=>{ctx.fillStyle='#253d42';ctx.fillRect(0,0,512,128);ctx.fillStyle='#f5dfab';ctx.textAlign='center';ctx.font='bold 62px sans-serif';ctx.fillText(t,256,87);texture.needsUpdate=true};redraw(text);return {m,redraw}}
function ensureHotelRoutes(){if(hotelInterior===null)return;const lobby=hotelFloors.lobby;if(!hotelRouteLobbies.has(lobby)){const lift=new T.Group();lift.position.set(-4.5,0,-7);lobby.add(lift);box(3,3.8,.14,'#ad9975',0,1.9,1.9,lift);box(2.7,3.3,.12,'#273d42',0,1.65,2,lift);box(2.8,.07,4,'#d9cbb0',0,.07,0,lift);box(2.8,3.4,.1,'#7e8d8e',0,1.7,-1.8,lift);for(const x of[-1.4,1.4])box(.1,3.4,4,'#a8b1ac',x,1.7,0,lift);const doors=[];for(const x of[-.63,.63])doors.push(box(1.23,3.15,.12,'#a3a8a1',x,1.6,2.1,lift));routePlaque('THANG MÁY',0,3.65,2.2,lift,3);routePlaque('G',0,3.25,2.21,lift,.6);box(.18,.45,.1,'#3a4b4c',1.62,1.4,2.05,lift);ball(.055,'#efc672',1.62,1.4,2.13,lift);hotelRouteLobbies.set(lobby,{doors,amount:0})}
if(!hotelCorridor){hotelCorridor=new T.Group();hotelCorridor.name='walkable-hotel-corridor';hotelCorridor.position.x=hotelBase;scene.add(hotelCorridor);box(18,.2,20,'#e5d7bf',0,-.1,0,hotelCorridor);box(3,.025,15,'#547c79',0,.03,3,hotelCorridor);for(const x of[-9,9])box(.2,4,20,'#eee5d2',x,2,0,hotelCorridor);for(const x of[-7.5,-2.5,2.5,7.5])box(3,3.8,.2,'#e9dfca',x,1.9,-3,hotelCorridor);for(let i=0;i<3;i++){const x=(i-1)*5;for(const side of[-.94,.94])box(.12,3.2,.25,'#8e7651',x+side,1.6,-3,hotelCorridor);box(2,.16,.25,'#8e7651',x,3.2,-3,hotelCorridor);const hinge=new T.Group();hinge.position.set(x-.85,0,-2.82);hotelCorridor.add(hinge);box(1.7,3,.12,'#5c5144',.85,1.5,0,hinge);box(.12,.4,.06,'#243c43',1.5,1.35,.1,hinge);ball(.035,'#e5ae69',1.5,1.4,.15,hinge);box(.28,.05,.07,'#cead68',1.45,1.17,.12,hinge);roomPlaques.push(routePlaque('208',x,3.5,-2.75,hotelCorridor,1.3));if(i===1){guestDoor=hinge;scannerLight=ball(.045,'#df805c',1.5,1.46,.16,hinge)}}for(let z=-1;z<9;z+=3)for(const x of[-7.8,7.8]){box(.12,.55,.3,'#a28b5b',x,2.4,z,hotelCorridor);ball(.12,new T.MeshStandardMaterial({color:'#fff3d8',emissive:'#ffd38d',emissiveIntensity:.7}),x,2.5,z,hotelCorridor)}box(3.3,.04,3,'#c9b89a',-5.5,.04,7,hotelCorridor);box(3.3,3.5,.15,'#9ca8a3',-5.5,1.75,8.8,hotelCorridor);routePlaque('THANG MÁY · G',-5.5,3.5,8.65,hotelCorridor,3);hotelCorridor.visible=false}hotelFloors.corridor=hotelCorridor;hotelCorridor.visible=hotelArea==='corridor';}
function corridorBlocks(x,z){if(Math.abs(x)>8.5||z>8.4||z< -4)return true;if(z< -2.4)return !(roomDoorOpen&&roomDoorAngle>.85&&Math.abs(x)<.65);return false}
function showRoomCard(){if(hotelInterior===null)return;liftCard.replaceChildren();const h=document.createElement('h2');h.textContent='🔑 Thẻ phòng '+(hotelBookings[hotelInterior]||'Chưa nhận');const info=document.createElement('p');info.textContent=hotelBookings[hotelInterior]?'Tầng '+String(hotelBookings[hotelInterior]).slice(0,-2)+' · Ocean Suite · 48 m² · giường đôi · ban công nhìn biển · bồn tắm. Thẻ chỉ mở đúng phòng. Đi thang máy, tới cửa có số này rồi quẹt thẻ.':'Hãy gặp lễ tân ở sảnh tầng G để nhận phòng và thẻ khóa.';const close=document.createElement('button');close.className='primary';close.textContent='Cất thẻ';close.onclick=()=>liftDialog.classList.add('hidden');liftCard.append(h,info,close);liftDialog.classList.remove('hidden');moveGoal=null;for(const k in keys)keys[k]=false}
function showLiftFloors(){if(elevatorRiding)return;liftCard.replaceChildren();const h=document.createElement('h2');h.textContent='🛗 Chọn tầng';liftCard.append(h);const p=document.createElement('p');p.textContent='Bạn đang ở '+(hotelArea==='lobby'?'tầng G':('tầng '+hotelFloorNumber))+' · '+(hotelBookings[hotelInterior]?'Thẻ phòng '+hotelBookings[hotelInterior]:'Chưa nhận thẻ phòng');liftCard.append(p);for(const floor of[0,2,3,4,5,6,7]){const b=document.createElement('button');b.textContent=floor===0?'G · Sảnh lễ tân':'Tầng '+floor;b.style.cssText='padding:12px;margin:4px;border-radius:10px;background:#365c58;color:white';b.onclick=()=>startLift(floor);liftCard.append(b)}const close=document.createElement('button');close.textContent='Ra khỏi thang máy';close.style.padding='12px';close.onclick=()=>{liftDialog.classList.add('hidden');player.position.set(hotelBase-4.5,0,hotelArea==='lobby'?-4:5.6)};liftCard.append(close);liftDialog.classList.remove('hidden');moveGoal=null;for(const k in keys)keys[k]=false}
function startLift(floor){elevatorDestination=floor;elevatorRiding=true;elevatorTravel=0;elevatorOpen=false;liftDialog.classList.add('hidden');moveGoal=null;for(const k in keys)keys[k]=false;toast('🛗 Cửa đang đóng · Đang đi tới '+(floor===0?'tầng G':'tầng '+floor))}
function returnHotelCorridor(){changeHotelArea('corridor');player.position.set(hotelBase,0,-1.4);roomDoorOpen=false;roomDoorAngle=0;guestDoor.rotation.y=0;hotelCooldown=1}
function hotelPhysicalAction(){if(hotelInterior===null||elevatorRiding)return false;const x=player.position.x-hotelBase,z=player.position.z;if(hotelArea==='lobby'){const npc=hotelFloors.lobby.getObjectByName('hotel-receptionist');if(Math.hypot(x-3.5,z+4)<2.5||(npc&&Math.hypot(x-npc.position.x,z-npc.position.z)<2.3)){openReception();return true}if(Math.hypot(x+4.5,z+4.8)<2.8||x< -3&&x> -6&&z< -5){if(!elevatorOpen){elevatorOpen=true;toast('Thang máy đã mở · Đi vào cabin phía trước')}else if(z< -5.9)showLiftFloors();return true}}if(hotelArea==='corridor'){if(Math.hypot(x+5.5,z-7)<2.5){showLiftFloors();return true}if(z<.2){if(Math.abs(x)<1.5){if(hotelBookings[hotelInterior]!==hotelFloorNumber+'08'){toast('🔴 Thẻ không đúng phòng · Phòng được giao: '+(hotelBookings[hotelInterior]||'Chưa nhận'));return true}roomDoorOpen=true;scannerLight.material.color.set('#68d38c');toast('🟢 Thẻ hợp lệ · Cửa đã mở, đi vào phòng');return true}if(Math.abs(Math.abs(x)-5)<1.5){toast('Phòng khác đang có khách · Thẻ của bạn không mở được');return true}}}return false}
function updateHotelJourney(dt,now){const inside=active&&hotelInterior!==null;journeyInfo.style.display=inside?'block':'none';journeyButton.style.display='none';if(!inside){if(hotelCorridor)hotelCorridor.visible=false;return}journeyInfo.textContent=elevatorRiding?'🛗 Đang di chuyển… '+Math.min(100,Math.round(elevatorTravel/3*100))+'%':hotelArea==='corridor'?'Tầng '+hotelFloorNumber+' · Thẻ '+(hotelBookings[hotelInterior]||'Chưa nhận'):'🔑 '+(hotelBookings[hotelInterior]?'Phòng '+hotelBookings[hotelInterior]:'Gặp lễ tân để nhận phòng')+' · '+(hotelArea==='lobby'?'Sảnh G':hotelArea==='suite'?'Trong phòng':'Khu tiện ích');if(elevatorRiding){hotelMenu.style.display='none';if(active)elevatorTravel+=dt;if(elevatorTravel>=3){elevatorRiding=false;hotelFloorNumber=elevatorDestination;roomDoorOpen=false;roomDoorAngle=0;changeHotelArea(elevatorDestination===0?'lobby':'corridor');player.position.set(hotelBase+(elevatorDestination===0?-4.5:-5.5),0,elevatorDestination===0?-4:5.5);elevatorOpen=elevatorDestination===0;roomPlaques.forEach((v,i)=>v.redraw(hotelFloorNumber+'0'+(i+7)));toast('Đã tới '+(elevatorDestination===0?'sảnh G':'tầng '+hotelFloorNumber)+' · Đi tới cửa phòng ghi trên thẻ')}return}const x=player.position.x-hotelBase,z=player.position.z;if(hotelArea==='lobby'){const data=hotelRouteLobbies.get(hotelFloors.lobby);if(data){data.amount+=(Number(elevatorOpen)-data.amount)*Math.min(1,dt*4);data.doors.forEach((d,i)=>d.position.x=(i?1:-1)*(.63+data.amount*1.1))}const npc=hotelFloors.lobby.getObjectByName('hotel-receptionist');if(npc){npc.visible=!receptionEscort;if(receptionEscort)greetingUntil=0;const greeting=now<greetingUntil;const goal=new T.Vector3(greeting?0:4,0,greeting?5.3:-7.8);npc.position.lerp(goal,Math.min(1,dt*1.2));npc.rotation.y=Math.atan2(x-npc.position.x,z-npc.position.z);if(npc.userData.arms?.[1])npc.userData.arms[1].rotation.x=greeting?-.8+Math.sin(now*.006)*.2:0;if(greeting){journeyButton.textContent='🛎 Lễ tân chào đón · Nhận phòng';journeyButton.style.display='block'}}if(Math.hypot(x-3.5,z+4)<2.7){journeyButton.textContent='🛎 Nói chuyện với lễ tân · E';journeyButton.style.display='block'}if(Math.hypot(x+4.5,z+4.8)<2.8||x< -3&&x> -6&&z< -5){journeyButton.textContent=elevatorOpen?'🛗 Đi vào cabin để chọn tầng':'🛗 Gọi thang máy · E';journeyButton.style.display='block'}if(elevatorOpen&&x> -5.6&&x< -3.4&&z< -6&&liftDialog.classList.contains('hidden'))showLiftFloors()}if(hotelArea==='corridor'){roomDoorAngle+=(Number(roomDoorOpen)-roomDoorAngle)*Math.min(1,dt*4);guestDoor.rotation.y=-roomDoorAngle*1.45;if(Math.hypot(x+5.5,z-7)<2.5){journeyButton.textContent='🛗 Vào thang máy · E';journeyButton.style.display='block'}else if(z<.2&&(Math.abs(x)<1.5||Math.abs(Math.abs(x)-5)<1.5)){journeyButton.textContent=roomDoorOpen?'🚪 Cửa đã mở · Đi vào phòng':'🔑 Quẹt thẻ mở cửa · E';journeyButton.style.display='block'}if(roomDoorOpen&&roomDoorAngle>.85&&Math.abs(x)<.65&&z< -3.4){changeHotelArea('suite');toast('Chào mừng vào phòng '+hotelBookings[hotelInterior])}}}

