function startReceptionEscort(mode){if(hotelInterior===null)return;receptionEscort=true;receptionEscortMode=mode;receptionGuideArea='';receptionGuideHint='';greetingUntil=0;receptionGuide.position.copy(player.position).add(new T.Vector3(1.2,0,0));if(mode==='guide'){if(hotelArea!=='lobby'){receptionEscortMode='follow';toast('Em đi cùng anh/chị · Thang máy ở cuối hành lang');}else{receptionGuideWaypoints=[new T.Vector3(hotelBase+.85,0,3.8),new T.Vector3(hotelBase+.85,0,-3.9),new T.Vector3(hotelBase-4.5,0,-4.1)];toast('Linh: Mời anh/chị đi theo em tới thang máy nhé!')}}else toast('Linh sẽ đi cùng bạn · Có thể hỏi thông tin phòng hoặc nhờ dẫn đường')}
