function vehicleInteraction(){if(!active)return false;if(driving){if(Math.abs(carSpeed)>1){toast('Dừng xe trước khi xuống nhé');return true}leaveSportsCar();return true}if(!inHouse&&!inCity&&hotelInterior===null&&player.position.distanceTo(sportCar.position)<4){if(fishingState!=='idle')cancelFishing();driving=true;carSpeed=0;cockpitView=false;orbitYaw=sportCar.rotation.y+Math.PI;orbitPitch=.16;moveGoal=null;spraying=false;neighborhoodView=campusOverview=false;mapPan.set(0,0,0);for(const k in keys)keys[k]=false;toast('W ga · S lùi · A/D đánh lái · Space phanh · V đổi camera · E xuống xe');return true}return false}
function leaveSportsCar(){const p=sportCar.position,angle=sportCar.rotation.y;const options=[[-2,0],[2,0],[0,-3],[0,3]];for(const [x,z]of options){const target=new T.Vector3(x,0,z).applyAxisAngle(new T.Vector3(0,1,0),angle).add(p);if(!isWorldBlocking(target.x,target.z)){player.position.copy(target);break}}driving=false;carSpeed=0;orbitPitch=.65;orbitDistance=innerWidth<=800?8:10;orbitYaw=player.rotation.y+Math.PI;player.visible=true;sportCar.userData.windshield.visible=true;sportCar.userData.carRoof.visible=true;sportCar.userData.driverSeat.forEach(o=>o.visible=true);moveGoal=null;for(const k in keys)keys[k]=false;}
